'use strict';

// MODULES //

var f32 = require( '@stdlib/number/float64/base/to-float32' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var sqrtf = require( '@stdlib/math/base/special/sqrtf' );
var toWord = require( '@stdlib/number/float32/base/to-word' );
var lnf = require( '@stdlib/math/base/special/lnf' );
var log1pf = require( '@stdlib/math/base/special/log1pf' );


// VARIABLES //

var ONE = f32( 1.0 );
var LN2 = f32( 6.9314718246e-01 );
var H1 = 0x3f800000|0;
var H2 = 0x4d800000|0;
var H3 = 0x7f800000|0;
var H4 = 0x40000000|0;


// MAIN //

/* eslint-disable no-else-return */

/* eslint-disable no-mixed-operators */

/**
* Computes the hyperbolic arccosine of a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {number} hyperbolic arccosine
*
* @example
* var v = acoshf( 1.0 );
* // returns 0.0
*
* @example
* var v = acoshf( 2.0 );
* // returns ~1.317
*
* @example
* var v = acoshf( NaN );
* // returns NaN
*/
function acoshf( x ) {
	var hx;
	var t;

	if ( isnanf( x ) || x < 1.0 ) {
		return NaN;
	}
	if ( x === 1.0 ) {
		return 0.0;
	}
	x = f32( x );
	hx = toWord( x ) | 0;
	if ( hx < H1 ) { // x < 1
		return f32( f32( x - x ) / f32( x - x ) );
	} else if ( hx >= H2 ) { // x > 2**28
		if ( hx >= H3 ) { // x is inf of NaN
			return f32( x + x );
		} else {
			return f32( lnf( x ) + LN2 ); // acosh(huge)=ln(2x)
		}
	} else if ( hx === H1 ) {
		return 0.0; // acosh(1) = 0
	} else if ( hx > H4 ) { // 2**28 > x > 2
		t = f32( x * x );
		return f32( lnf( f32( f32( 2.0 * x ) - f32( ONE / f32( x + sqrtf( f32( t - ONE ) ) ) ) ) ) ); // eslint-disable-line max-len
	} else { // 1<x<2
		t = f32( x - ONE );
		return f32( log1pf( f32( t + sqrtf( f32( f32( 2.0 ) * t + f32( t * t ) ) ) ) ) ); // eslint-disable-line max-len
	}
}


// EXPORTS //

module.exports = acoshf;
